[{"order":1,"type":"heading","text":"PHP Standards Recommendations (PSRs): A Comprehensive Guide"},{"order":2,"type":"paragraph","text":"PHP Standards Recommendations (PSRs) are specifications published by the PHP Framework Interop Group (PHP-FIG) to standardize coding practices in PHP. Adhering to PSRs promotes code interoperability, readability, and maintainability. This tutorial covers PSR-1, PSR-2, PSR-4, PSR-7, and PSR-12."},{"order":3,"type":"subheading","text":"PSR-1: Basic Coding Standard"},{"order":4,"type":"paragraph","text":"PSR-1 defines the basic coding elements that should be followed to ensure a base level of technical interoperability. Key aspects include:"},{"order":5,"type":"bullet_point","text":"Files MUST use only <?php tags or <?php echo tags."},{"order":6,"type":"bullet_point","text":"Files MUST be encoded in UTF-8 without BOM."},{"order":7,"type":"bullet_point","text":"Classes, functions, and constants MUST be declared using "StudlyCaps" for class names and "snake_case" for function and constant names."},{"order":8,"type":"bullet_point","text":"Class constants MUST be declared in all upper case with underscore separators."},{"order":9,"type":"code","text":"<?php

namespace My\Namespace;

use Some\Other\Class;

class MyClass
{
    const CONSTANT_VALUE = 'value';

    public function myFunction()
    {
        // ...
    }
}
"},{"order":10,"type":"subheading","text":"PSR-2: Coding Style Guide"},{"order":11,"type":"paragraph","text":"PSR-2 builds upon PSR-1 by providing more detailed guidelines for code formatting. It focuses on readability and consistency. Some important rules are:"},{"order":12,"type":"bullet_point","text":"Code MUST use 4 spaces for indentation, not tabs."},{"order":13,"type":"bullet_point","text":"Each line MUST NOT exceed 120 characters; lines SHOULD be 80 characters or less."},{"order":14,"type":"bullet_point","text":"There MUST be one blank line after the namespace declaration, and one blank line after the use block."},{"order":15,"type":"bullet_point","text":"Opening braces for classes and methods MUST go on their own line, and closing braces MUST go on their own line."},{"order":16,"type":"bullet_point","text":"Visibility MUST be declared on all properties and methods; abstract and final MUST be declared before the visibility; static MUST be declared after the visibility."},{"order":17,"type":"bullet_point","text":"Control structure keywords MUST have one space after them; method and function calls MUST NOT have a space between the method or function name and the opening parenthesis; arguments MUST NOT have a space before each comma, but MUST have one space after each comma."},{"order":18,"type":"code","text":"<?php

namespace My\Namespace;

use Some\Other\Class;

class MyClass
{
    public function myFunction($arg1, $arg2)
    {
        if ($arg1 === $arg2) {
            // ...
        }
    }
}
"},{"order":19,"type":"subheading","text":"PSR-4: Autoloader"},{"order":20,"type":"paragraph","text":"PSR-4 specifies an autoloader that allows PHP to automatically load class files based on their namespace. It defines a standard for mapping namespaces to file paths."},{"order":21,"type":"bullet_point","text":"A fully qualified class name has the following form: <NamespaceName>\<SubNamespaceNames>\<ClassName>."},{"order":22,"type":"bullet_point","text":"Each namespace MUST have a top-level namespace name (the "vendor namespace")."},{"order":23,"type":"bullet_point","text":"Each namespace separator is converted to a DIRECTORY_SEPARATOR when loading from the file system."},{"order":24,"type":"bullet_point","text":"Each underscore (_) character in the CLASS NAME is converted to a DIRECTORY_SEPARATOR. The underscore character has no special meaning in the namespace."},{"order":25,"type":"code","text":"<?php

// File: /path/to/project/src/My/ClassName.php

namespace My;

class ClassName
{
    // ...
}

// Autoloader example:

spl_autoload_register(function ($class) {
    $prefix = 'My\\';
    $base_dir = __DIR__ . '/src/';

    $len = strlen($prefix);
    if (strncmp($prefix, $class, $len) !== 0) {
        return;
    }

    $relative_class = substr($class, $len);
    $file = $base_dir . str_replace('\\', '/', $relative_class) . '.php';

    if (file_exists($file)) {
        require $file;
    }
});
"},{"order":26,"type":"subheading","text":"PSR-7: HTTP Message Interfaces"},{"order":27,"type":"paragraph","text":"PSR-7 defines interfaces for representing HTTP messages, including requests and responses. It provides a standard way to interact with HTTP messages in a framework-agnostic manner."},{"order":28,"type":"bullet_point","text":"Defines interfaces for Request, Response, Stream, and URI."},{"order":29,"type":"bullet_point","text":"Allows for immutable message objects, promoting predictable behavior."},{"order":30,"type":"code","text":"<?php

use Psr\Http\Message\RequestInterface;
use Psr\Http\Message\ResponseInterface;

function processRequest(RequestInterface $request, ResponseInterface $response)
{
    $uri = $request->getUri();
    $path = $uri->getPath();

    $response->getBody()->write('You requested: ' . $path);

    return $response;
}
"},{"order":31,"type":"subheading","text":"PSR-12: Extended Coding Style Guide"},{"order":32,"type":"paragraph","text":"PSR-12 is an evolution of PSR-2, providing more specific and modern coding style guidelines. It aims to improve code consistency and readability further."},{"order":33,"type":"bullet_point","text":"Builds upon PSR-2 and clarifies ambiguous areas."},{"order":34,"type":"bullet_point","text":"Adds rules for modern PHP features like traits, closures, and short array syntax."},{"order":35,"type":"bullet_point","text":"Specifies how to format multi-line constructs, such as method calls and array declarations."},{"order":36,"type":"code","text":"<?php

namespace My\Namespace;

class MyClass
{
    public function myFunction(
        string $arg1,
        int $arg2
    ):
    string {
        return 'Hello, world!';
    }

    public function anotherFunction()
    {
        $array = [
            'key1' => 'value1',
            'key2' => 'value2',
        ];
    }
}
"},{"order":37,"type":"paragraph","text":"By adhering to these PSR standards, PHP developers can create code that is more consistent, readable, and interoperable, leading to better collaboration and maintainability."}]
